import sys

def can_make_k_balanced(n, k, s):
    def is_possible():
        balance = [0] * (n - k + 1)
        question_marks = [0] * (n - k + 1)

        for i in range(k):
            if s[i] == '0':
                balance[0] -= 1
            elif s[i] == '1':
                balance[0] += 1
            else:
                question_marks[0] += 1

        if abs(balance[0]) > question_marks[0]:
            return False

        for i in range(k, n):
            if s[i - k] == '0':
                balance[i - k + 1] = balance[i - k] + 1
            elif s[i - k] == '1':
                balance[i - k + 1] = balance[i - k - 1] - 1
            else:
                balance[i - k + 1] = balance[i - k]

            if s[i] == '0':
                balance[i - k + 1] -= 1
            elif s[i] == '1':
                question_marks[i - k + 1] = question_marks[i - k]
                balance[i - k + 1] += 1
            else:
                question_marks[i - k + 1] = question_marks[i -k] + 1

            if abs(balance[i - k + 1]) > question_marks[i - k + 1]:
                return False

        return True

    return "YES" if is_possible() else "NO"

input = sys.stdin.read().split()
t = int(input[0])
index = 1
results = []

for _ in range(t):
    n = int(input[index])
    k = int(input[index + 1])
    s = input[index + 2]
    index += 3
    results.append(can_make_k_balanced(n, k, s))

print("\n".join(results))
